tasks.solution:
def rot13(s):
    return s.translate(str.maketrans('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz','NOPQRSTUVWXYZABCDEFGHIJKLMnopqrstuvwxyzabcdefghijklm'))

def decode_blob(b64):
    raw = base64.b64decode(b64, validate=True).decode()
    return rot13(raw)[::-1]

def is_injection(value: str) -> bool:
    v = value.lower()
    patterns = ["' or", '" or', 'union select', '; drop', '--', 'sleep(']
    return any(p in v for p in patterns)

